// Generated by perch. Regenerating overwrites this file.
//
// What a menu item or quit button does when chosen, and the quit prompt that
// runs one before the app terminates.

import AppKit
import Foundation

// MARK: - Actions

/// Called exactly once when an action finishes, on the main thread, with
/// whether it succeeded. A failure has already been alerted.
typealias Done = (Bool) -> Void

enum Act {
    /// Every action completes, and the menu re-polls on completion so acting on
    /// it visibly changes it. A non-zero exit raises an alert naming the command.
    static func run(_ argv: [String], then done: @escaping Done) {
        DispatchQueue.global(qos: .userInitiated).async {
            let outcome = Watcher.run(argv)
            DispatchQueue.main.async {
                if !outcome.ok { alert(argv.joined(separator: " "), outcome.err) }
                done(outcome.ok)
            }
        }
    }

    static func open(_ target: String, then done: @escaping Done) {
        let url: URL
        if let parsed = URL(string: target), parsed.scheme != nil {
            url = parsed
        } else {
            url = URL(fileURLWithPath: (target as NSString).expandingTildeInPath)
        }
        let ok = NSWorkspace.shared.open(url)
        if !ok { alert("Opening \(target)", "Nothing could open it.") }
        done(ok)
    }

    /// Text as the inside of a JSON string, for a hole in a post: body.
    static func jsonEscaped(_ s: String) -> String {
        var out = ""
        for u in s.unicodeScalars {
            switch u {
            case "\"": out += "\\\""
            case "\\": out += "\\\\"
            case "\n": out += "\\n"
            case "\r": out += "\\r"
            case "\t": out += "\\t"
            case _ where u.value < 0x20: out += String(format: "\\u%04x", u.value)
            default: out.unicodeScalars.append(u)
            }
        }
        return out
    }

    /// Typed text as one query component. urlQueryAllowed leaves & + = alone,
    /// which would split the text into several parameters.
    static func urlQuery(_ s: String) -> String {
        let unreserved = CharacterSet(charactersIn:
            "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789-._~")
        return s.addingPercentEncoding(withAllowedCharacters: unreserved) ?? ""
    }

    /// Hand-written Swift from menubar/Sources/. It re-polls like every other
    /// action, and raises no alert: there is no exit status to inspect, so
    /// reporting a failure belongs to the hook.
    static func swift(_ body: () -> Void, then done: @escaping Done) {
        body()
        done(true)
    }

    static func post(_ urlString: String, body: String, then done: @escaping Done) {
        guard let url = URL(string: urlString) else {
            alert("POST \(urlString)", "Not a URL.")
            done(false)
            return
        }
        var request = URLRequest(url: url)
        request.httpMethod = "POST"
        request.setValue("application/json", forHTTPHeaderField: "Content-Type")
        request.httpBody = body.data(using: .utf8)
        URLSession.shared.dataTask(with: request) { _, response, error in
            DispatchQueue.main.async {
                let status = (response as? HTTPURLResponse)?.statusCode ?? 0
                let ok = error == nil && (200..<300).contains(status)
                if !ok { alert("POST \(urlString)", error?.localizedDescription ?? "HTTP \(status)") }
                done(ok)
            }
        }.resume()
    }

    /// The three things perch will do to a LaunchAgent. The verbs are the
    /// modern ones: `load`/`unload` also write launchd's disabled database,
    /// which is a second effect nobody asking for Start is asking for.
    static func agent(label: String, plist: String, verb: LaunchAgentVerb, then done: @escaping Done) {
        DispatchQueue.global(qos: .userInitiated).async {
            let outcome: RunOutcome
            switch verb {
            case .start:
                outcome = bootstrap(label: label, plist: plist)
            case .stop:
                outcome = Watcher.run(["launchctl", "bootout", Launchd.target(label)], timeout: 10)
            case .restart:
                outcome = restart(label: label, plist: plist)
            case .enable:
                outcome = Watcher.run(["launchctl", "enable", Launchd.target(label)], timeout: 10)
            case .disable:
                outcome = Watcher.run(["launchctl", "disable", Launchd.target(label)], timeout: 10)
            }
            DispatchQueue.main.async {
                if !outcome.ok { alert(verb.gerund + " " + label, outcome.err) }
                done(outcome.ok)
            }
        }
    }

    /// bootout returns before launchd has let go of the label, and
    /// bootstrapping into that gap fails with Input/output error — so this
    /// polls until the label is genuinely gone rather than bootstrapping blind.
    private static func restart(label: String, plist: String) -> RunOutcome {
        _ = Watcher.run(["launchctl", "bootout", Launchd.target(label)], timeout: 10)
        for _ in 0..<40 {
            if !Watcher.run(["launchctl", "print", Launchd.target(label)], timeout: 10).ok {
                return bootstrap(label: label, plist: plist)
            }
            Thread.sleep(forTimeInterval: 0.05)
        }
        return RunOutcome(
            ok: false, code: -1, out: "",
            err: "launchd still holds \(label) after two seconds, so it was not bootstrapped again."
        )
    }

    /// launchd refuses to bootstrap a disabled label, and disabling is how a
    /// job is kept from starting at login — so starting one by hand enables
    /// it for the bootstrap and disables it again, which leaves it running.
    private static func bootstrap(label: String, plist: String) -> RunOutcome {
        let start = ["launchctl", "bootstrap", Launchd.domain, Launchd.expand(plist)]
        guard Launchd.disabled(label) else { return Watcher.run(start, timeout: 10) }
        let enabled = Watcher.run(["launchctl", "enable", Launchd.target(label)], timeout: 10)
        guard enabled.ok else { return enabled }
        let outcome = Watcher.run(start, timeout: 10)
        _ = Watcher.run(["launchctl", "disable", Launchd.target(label)], timeout: 10)
        return outcome
    }

    static func perform(_ action: MenuAction, then done: @escaping Done) {
        switch action {
        case .run(let argv): run(argv, then: done)
        case .open(let target): open(target, then: done)
        case .post(let url, let body): post(url, body: body, then: done)
        case .agent(let label, let plist, let verb): agent(label: label, plist: plist, verb: verb, then: done)
        case .swift(let body): swift(body, then: done)
        case .window(let verb): Windows.perform(verb, then: done)
        case .quit: NSApp.terminate(nil)
        }
    }

    /// How a failure is reported. A variable so a headless probe can see one
    /// without a modal nobody is there to dismiss.
    static var alert: (_ command: String, _ detail: String) -> Void = modal

    private static func modal(_ command: String, _ detail: String) {
        let a = NSAlert()
        a.messageText = "\(command) failed"
        a.informativeText = detail.isEmpty ? "No output." : detail
        a.alertStyle = .warning
        a.runModal()
    }
}

// MARK: - Quitting

/// One answer in the quit prompt. A nil action just quits.
struct QuitChoice {
    let text: String
    let action: MenuAction?
}

/// What quitting asks. Cancel is implicit and always last; the first button is
/// the default.
struct QuitPrompt {
    let message: String
    let detail: String
    let buttons: [QuitChoice]
}

enum Quit {
    /// Quit reasons that mean the machine is going down or the user is walking
    /// away — nobody is asking this app a question, and nobody is waiting to
    /// answer one.
    private static let unattended: Set<OSType> = [
        OSType(kAELogOut), OSType(kAEReallyLogOut),
        OSType(kAEShutDown), OSType(kAERestart), OSType(kAEQuitAll),
    ]

    /// Whether this termination is aimed at this app specifically. An absent
    /// event or an absent reason means it is: NSApp.terminate from our own
    /// menus and from the Dock tile carries no quit reason at all.
    static func isUserInitiated(_ event: NSAppleEventDescriptor?) -> Bool {
        guard let reason = event?.attributeDescriptor(forKeyword: AEKeyword(kAEQuitReason)) else {
            return true
        }
        return !unattended.contains(reason.enumCodeValue)
    }

    /// Asks, and reports what to do. A helper that cancels someone's logout is
    /// worse than one that exits without asking, and a modal raised during
    /// shutdown is a dialog nobody is there to dismiss — so an unattended quit
    /// never reaches the alert.
    static func should(_ prompt: QuitPrompt?,
                       event: NSAppleEventDescriptor?,
                       then finish: @escaping (Bool) -> Void) -> NSApplication.TerminateReply {
        guard let prompt, isUserInitiated(event) else { return .terminateNow }

        let alert = NSAlert()
        alert.messageText = prompt.message
        alert.informativeText = prompt.detail
        let choices = prompt.buttons.isEmpty ? [QuitChoice(text: "Quit", action: nil)] : prompt.buttons
        for choice in choices {
            alert.addButton(withTitle: choice.text)
        }
        alert.addButton(withTitle: "Cancel").keyEquivalent = "\u{1b}"

        // The status item does not activate the app, so an unactivated modal can
        // sit behind another app with nothing to click while runModal blocks.
        NSApp.activate(ignoringOtherApps: true)

        let picked = alert.runModal().rawValue - NSApplication.ModalResponse.alertFirstButtonReturn.rawValue
        guard picked >= 0, picked < choices.count else { return .terminateCancel }
        guard let action = choices[picked].action else { return .terminateNow }

        // Captured strongly on purpose: every path out of this has to reply
        // exactly once, and a dropped reply hangs termination forever. A failed
        // action has been alerted, and cancels the quit.
        Act.perform(action) { ok in finish(ok) }
        return .terminateLater
    }
}

/// The app's one window, if it declared one. Set at launch by the generated
/// Controller. A closure rather than a typed reference so Runtime.swift does not
/// depend on Window.swift, which is emitted only when there is a window.
enum Windows {
    static var handler: ((WindowVerb) -> Void)?

    static func perform(_ verb: WindowVerb, then done: @escaping Done) {
        handler?(verb)
        done(true)
    }
}
